er:1px solid var(--line)}.planner-card{padding:38px;box-shadow:0 20px 60px rgba(47,42,32,.08)}.form-label{font-size:.76rem;font-weight:700;text-transform:uppercase;letter-spacing:.08em;color:#626a61}.form-control,.form-select{border-radius:0;border:1px solid #d9d4ca;background:#fff;padding:13px 14px;color:var(--ink)}.form-control:focus,.form-select:focus{border-color:var(--green2);box-shadow:0 0 0 .2rem rgba(83,102,77,.1)}textarea.form-control{min-height:190px;line-height:1.7}.note{font-size:.78rem;color:var(--muted)}.photo-card{height:420px;position:relative;overflow:hidden;background:#ddd}.photo-card img{width:100%;height:100%;object-fit:cover;transition:transform 1.2s ease}.photo-card:hover img{transform:scale(1.045)}.photo-caption{position:absolute;left:22px;bottom:20px;color:#fff;z-index:2}.photo-card:after{content:'';position:absolute;inset:35% 0 0;background:linear-gradient(transparent,rgba(0,0,0,.7))}.photo-caption h3{margin:0;font-size:1.7rem}.inspiration-row{display:flex;gap:18px;overflow:auto;padding-bottom:12px;scrollbar-width:none}.inspiration-row::-webkit-scrollbar{display:none}.inspire{min-width:235px;height:310px;position:relative;overflow:hidden}.inspire img{width:100%;height:100%;object-fit:cover;transition:transform .8s}.inspire:hover img{transform:scale(1.06)}.inspire span{position:absolute;left:18px;bottom:17px;color:#fff;font-weight:700;z-index:2}.process{background:#303a2d;color:#fff}.step{border-top:1px solid rgba(255,255,255,.2);padding:22px 0}.step small{color:#bfc9b9}.result{display:none}.result-head{background:#303a2d;color:#fff;padding:50px 0}.result-card{background:#fff;border:1px solid var(--line);padding:28px;height:100%}.metric{font-size:2rem;font-family:'Playfair Display';font-weight:600}.floor-wrap{background:#f0ede6;padding:18px;overflow:auto}.floor{position:relative;background:#fff;border:2px solid #2d332d;min-width:650px;height:470px}.room{position:absolute;border:1px solid #51584f;background:#fbfaf6;display:flex;flex-direction: