<script>
$(function(){
 let slide=0,slides=$('.hero-slide');setInterval(function(){slides.eq(slide).removeClass('active');slide=(slide+1)%slides.length;slides.eq(slide).addClass('active')},6500);
 const msgs=['Inasoma maelezo yako.','Inatambua spaces na functions.','Inaangalia plot na proportions.','Inapanga circulation.','Inaandaa architectural concept.'];
 function esc(v){return $('<div>').text(v==null?'':v).html()}
 function renderPlan(p){$('#rTitle').text(p.title||'Architectural Concept');$('#rSummary').text(p.summary||'');$('#houseW').text(Number(p.house_width||0).toFixed(2));$('#houseD').text(Number(p.house_depth||0).toFixed(2));let rooms=Array.isArray(p.rooms)?p.rooms:[];$('#roomCount').text(rooms.length);$('#dimensions').html(rooms.map(r=>`<div class="d-flex justify-content-between border-bottom py-2"><span>${esc(r.name)}</span><strong>${Number(r.width).toFixed(2)} × ${Number(r.depth).toFixed(2)} m</strong></div>`).join(''));let flow=rooms.map((r,i)=>`<div class="flow-line"><div class="flow-num">${i+1}</div><div><strong>${esc(r.name)}</strong><div class="note">${Number(r.width).toFixed(2)} × ${Number(r.depth).toFixed(2)} m</div></div></div>`).join('');$('#flow').html(flow||'<p class="text-secondary">Hakuna room flow iliyotolewa.</p>');$('#outside').text(p.outside_preview||'Exterior concept itaendana na mpangilio wa ndani, entrance, daylight, veranda/terrace na materials zilizoelezwa kwenye brief.');
 const W=Math.max(8,Number(p.house_width)||12),D=Math.max(8,Number(p.house_depth)||16),cw=620,ch=440, gap=2;let x=0,y=0,rowH=0;let html='';rooms.forEach((r,i)=>{let rw=Math.max(1,Number(r.width)||3),rd=Math.max(1,Number(r.depth)||3);let px=Math.min(260,Math.max(75,rw/W*520));let py=Math.min(190,Math.max(65,rd/D*390));if(x+px>610){x=0;y+=rowH+gap;rowH=0}if(y+py>430){x=0;y=0}html+=`<div class="room" style="left:${x}px;top:${y}px;width:${px}px;height:${py}px"><strong>${esc(r.name)}</strong><em>${rw.toFixed(2)} × ${rd.toFixed(2)} m</em></div>`;x+=px+gap;rowH=Math.max(rowH,py)});$('#floor').html(html);$('#results').fadeIn(450);$('html,body').animate({scrollTop:$('#results').offset().top-70},700)}
 $('#plannerForm').on('submit',function(e){e.preventDefault();let data={};$(this).serializeArray().forEach(x=>data[x.name]=x.value);$('#loading').css('display','flex');let i=0;$('#loadingText').text(msgs[0]);let timer=setInterval(()=>{$('#loadingText').text(msgs[++i%msgs.length])},1100);$('.btn-text').addClass('d-none');$('.spinner-border').removeClass('d-none');$('#clarify').addClass('d-none').empty();$.ajax({url:'api/generate.php',method:'POST',contentType:'application/json',data:JSON.stringify(data),dataType:'json',timeout:90000}).done(function(res){if(!res.ok){alert(res.message||'AI service haikupatikana.');return}let p=res.plan||{};if(p.needs_clarification){$('#clarify').removeClass('d-none').html('<strong>AI inahitaji clarification:</strong><ul class="mb-0 mt-2">'+(p.questions||[]).map(q=>'<li>'+esc(q)+'</li>').join('')+'</ul>');$('#results').fadeIn(350);$('html,body').animate({scrollTop:$('#results').offset().top-70},600);return}renderPlan(p)}).fail(function(xhr){let m='Imeshindikana kuwasiliana na AI service.';try{let j=JSON.parse(xhr.responseText);if(j.message)m=j.message}catch(e){}alert(m)}).always(function(){clearInterval(timer);$('#loading').hide();$('.btn-text').removeClass('d-none');$('.spinner-border').addClass('d-none')})});
 $('a[href^="#"]').on('click',function(e){let t=$(this).attr('href');if(t&&t!=='#'&&$(t).length){e.preventDefault();$('html,body').animate({scrollTop:$(t).offset().top-65},500)}});
});
</script>
